(function(){var v=document.querySelector('.story-film video'),b=document.querySelector('.story-film__toggle');if(!v)return;var reduced=matchMedia('(prefers-reduced-motion: reduce)');function sync(){b.textContent=v.paused?'Play':'Pause';b.setAttribute('aria-label',(v.paused?'Play':'Pause')+' wedding highlights');}if(reduced.matches){v.autoplay=false;v.pause();}b.addEventListener('click',function(){if(v.paused){v.play().catch(sync);}else{v.pause();}});v.addEventListener('play',sync);v.addEventListener('pause',sync);sync();})();